cards.solution:
public class Main {
    public static void main(String[] args) {
        String username = "admin_budi";
        System.out.println(username.startsWith("admin"));
        System.out.println(username.indexOf("_"));
        System.out.println(username.charAt(username.length() - 1));
    }
}

